#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Grids;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Effects;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2.Vanilla.StateMachine;
using MVZ2Logic;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Grids;
using PVZEngine.Models;
using PVZEngine.Timing;
using PVZEngine.Tools;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Effects
{
    [AutoEntityBehaviourDefinition(VanillaEffectNames.krakenLandTentacle)]
    public class KrakenLandTentacle : AIEntityBehaviour
    {
        public KrakenLandTentacle(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            stateMachine.Init(entity);
            stateMachine.StartState(entity, STATE_APPEAR);
            UpdateModel(entity);
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            stateMachine.UpdateAI(entity);
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            stateMachine.UpdateLogic(entity);
            UpdateModel(entity);
        }
        public override void PostDeath(Entity entity, DeathInfo deathInfo)
        {
            base.PostDeath(entity, deathInfo);
            stateMachine.StartState(entity, STATE_DEATH);
        }
        private static void UpdateModel(Entity entity)
        {
            entity.SetAnimationInt("GunDirection", GetAnimationGunDirection(entity));
            entity.SetAnimationFloat("GunRotation1", GetGunRotation1(entity));
            entity.SetAnimationFloat("GunRotation2", GetGunRotation2(entity));
        }
        public static void DestroyWholeLane(Entity entity)
        {
            DestroyTiles(entity, entity.GetLane(), 0, entity.Level.GetMaxColumnCount() - 1);
        }
        public static void DestroyTiles(Entity entity, int lane, int minColumn, int maxColumn)
        {
            var level = entity.Level;
            for (int i = minColumn; i <= maxColumn; i++)
            {
                var tile = level.GetGrid(i, lane);
                if (tile == null)
                    continue;
                BreakTile(entity, tile);
            }

            using var enemiesItem = ListPool<Entity>.Rent();
            var enemies = enemiesItem.Value;
            entity.Level.FindEntitiesNonAlloc(e => e.Type == EntityTypes.ENEMY && e.GetLane() == lane && e.GetColumn() >= minColumn && e.GetColumn() <= maxColumn, enemies);

            if (enemies.Count > 0)
            {
                var damageEffects = new DamageEffectList(VanillaDamageEffects.INSTA_KILL);
                foreach (var enemy in enemies)
                {
                    enemy.Die(damageEffects);
                }
            }
        }
        public static void BreakTile(Entity source, LawnGrid tile)
        {
            var damageEffects = new DamageEffectList(VanillaDamageEffects.INSTA_KILL);
            using var gridEntities = tile.GetEntitiesDisposeable();
            foreach (var entity in gridEntities.Value)
            {
                entity.Die(damageEffects, entity);
            }

            var buff = tile.GetFirstBuff<BrokenTileBuff>();
            if (buff == null)
            {
                buff = tile.AddBuff<BrokenTileBuff>();

                var position = tile.GetCenterPosition();
                var spawnParams = source.GetSpawnParams();
                spawnParams.SetProperty(EngineEntityProps.TINT, Color.gray);
                source.Spawn(VanillaEffectID.smokeCluster, position, spawnParams);
                source.Level.PlaySound(VanillaSoundID.smash, position);
            }
            else
            {
                var timeoutTimer = buff.GetProperty<FrameTimer>(BrokenTileBuff.PROP_TIMEOUT_TIMER);
                timeoutTimer?.Reset();
            }
        }
        public static Vector3 GetNearTentaclePosition(Entity entity)
        {
            var offset = NEAR_TENTACLE_POSITION;
            offset.x *= entity.GetFacingX();
            return entity.Position + offset;
        }
        public static Vector3 GetFarTentaclePosition(Entity entity)
        {
            var offset = FAR_TENTACLE_POSITION;
            offset.x *= entity.GetFacingX();
            return entity.Position + offset;
        }
        public static int GetAnimationGunDirection(Entity entity)
        {
            if (entity.State == STATE_IDLE)
            {
                if (GetFaceUp(entity))
                {
                    return 1;
                }
                else
                {
                    return -1;
                }
            }
            return 0;
        }
        public static void SetFaceUp(Entity entity, bool value) => entity.SetProperty(PROP_FACE_UP, value);
        public static bool GetFaceUp(Entity entity) => entity.GetProperty<bool>(PROP_FACE_UP);
        public static void SetGunRotation1(Entity entity, float value) => entity.SetProperty(PROP_GUN_ROTATION_1, value);
        public static float GetGunRotation1(Entity entity) => entity.GetProperty<float>(PROP_GUN_ROTATION_1);
        public static void SetGunRotation2(Entity entity, float value) => entity.SetProperty(PROP_GUN_ROTATION_2, value);
        public static float GetGunRotation2(Entity entity) => entity.GetProperty<float>(PROP_GUN_ROTATION_2);
        public const int STATE_IDLE = VanillaEffectStates.IDLE;
        public const int STATE_APPEAR = VanillaEffectStates.KRAKEN_LAND_TENTACLE_APPEAR;
        public const int STATE_DEATH = VanillaEffectStates.KRAKEN_LAND_TENTACLE_DEATH;

        public const int ANIMATION_STATE_IDLE = 0;
        public const int ANIMATION_STATE_APPEAR = 10001;
        public const int ANIMATION_STATE_SHAKE = 10002;

        public static readonly Vector3 NEAR_TENTACLE_POSITION = new Vector3(270, 80, 0);
        public static readonly Vector3 FAR_TENTACLE_POSITION = new Vector3(570, 80, 0);

        public static readonly VanillaEntityPropertyMeta<bool> PROP_FACE_UP = new VanillaEntityPropertyMeta<bool>("face_up");
        public static readonly VanillaEntityPropertyMeta<float> PROP_GUN_ROTATION_1 = new VanillaEntityPropertyMeta<float>("gun_rotation_1");
        public static readonly VanillaEntityPropertyMeta<float> PROP_GUN_ROTATION_2 = new VanillaEntityPropertyMeta<float>("gun_rotation_2");

        private static readonly KrakenLandTentacleStateMachine stateMachine = new KrakenLandTentacleStateMachine();

        public class KrakenLandTentacleStateMachine : EntityStateMachine
        {
            public KrakenLandTentacleStateMachine()
            {
                AddState(new IdleState());
                AddState(new AppearState());
                AddState(new DeathState());
            }
        }
        public class IdleState : EntityStateMachineState
        {
            public IdleState() : base(STATE_IDLE, ANIMATION_STATE_IDLE) { }
            public override void OnUpdateLogic(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateLogic(machine, entity);
                DestroyWholeLane(entity);
            }
        }
        public class AppearState : EntityStateMachineState
        {
            public AppearState() : base(STATE_APPEAR, ANIMATION_STATE_APPEAR) { }
            public override void OnEnter(EntityStateMachine machine, Entity entity)
            {
                base.OnEnter(machine, entity);
                var timer = machine.GetSubStateTimer(entity);
                timer.ResetSeconds(1.5f);
            }
            public override void OnUpdateLogic(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateLogic(machine, entity);
                var timer = machine.GetSubStateTimer(entity);
                timer.Run(machine.GetSpeed(entity));
                var substate = machine.GetSubState(entity);

                var maxColumnCount = entity.Level.GetMaxColumnCount();
                var columnCount = Mathf.RoundToInt(timer.GetPassedPercentage() * (maxColumnCount - 3) + 3);
                var startColumn = entity.GetColumn();
                var endColumn = entity.GetMirroredColumn(startColumn - columnCount, false);
                var minColumn = Mathf.Min(startColumn, endColumn);
                var maxColumn = Mathf.Max(startColumn, endColumn);
                DestroyTiles(entity, entity.GetLane(), minColumn, maxColumn);

                if (timer.Expired)
                {
                    machine.StartState(entity, STATE_IDLE);
                    entity.PlaySound(VanillaSoundID.krakenHatchOpen);
                }
            }
        }
        public class DeathState : EntityStateMachineState
        {
            public DeathState() : base(STATE_DEATH, ANIMATION_STATE_SHAKE) { }
            public override void OnEnter(EntityStateMachine machine, Entity entity)
            {
                base.OnEnter(machine, entity);
                var timer = machine.GetSubStateTimer(entity);
                timer.ResetSeconds(2f);
            }
            public override void OnUpdateLogic(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateLogic(machine, entity);
                var timer = machine.GetSubStateTimer(entity);
                timer.Run(machine.GetSpeed(entity));
                if (timer.Expired)
                {
                    entity.PlaySound(VanillaSoundID.largeExplosion);
                    Explosion.Spawn(entity, GetNearTentaclePosition(entity), 120f);
                    Explosion.Spawn(entity, GetFarTentaclePosition(entity), 120f);
                    entity.Remove();
                }
            }
        }
    }
}
